package de.schaepi.puls180;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.time.*;import java.time.format.*;import java.util.*;
public final class DirectStore extends SQLiteOpenHelper{
private final Context context;public DirectStore(Context c){super(c,"direct-readings.db",null,2);context=c;}
public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE readings(id TEXT PRIMARY KEY,time TEXT NOT NULL,sys REAL NOT NULL,dia REAL NOT NULL,pulse REAL,estimated INTEGER NOT NULL,status INTEGER,device TEXT)");}
public void onUpgrade(SQLiteDatabase db,int old,int next){if(old<2){db.execSQL("ALTER TABLE readings ADD COLUMN status INTEGER");db.execSQL("ALTER TABLE readings ADD COLUMN device TEXT");}}
public static class Entry{public String id;public Instant time;public double sys,dia,pulse;public boolean estimated;public Integer status;}
public boolean save(BleMeasurement m,String device,byte[] packet){if(!License.allowed(context))return false;Instant time;boolean estimated=false;try{java.time.LocalDateTime local=LocalDateTime.parse(m.time,DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss"));if(local.getYear()<1900)throw new IllegalArgumentException();time=local.atZone(ZoneId.systemDefault()).toInstant();}catch(Exception e){time=Instant.now();estimated=true;}
String id=estimated?UUID.randomUUID().toString():UUID.nameUUIDFromBytes((device+":"+m.time+":"+Arrays.toString(packet)).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();SQLiteDatabase db=getWritableDatabase();try(Cursor c=db.rawQuery("SELECT id FROM readings WHERE id=?",new String[]{id})){if(c.moveToFirst())return false;}ContentValues v=new ContentValues();v.put("id",id);v.put("time",time.toString());v.put("sys",m.sys);v.put("dia",m.dia);if(Double.isFinite(m.pulse)&&m.pulse>0)v.put("pulse",m.pulse);v.put("estimated",estimated?1:0);if(m.measurementStatus!=null)v.put("status",m.measurementStatus);v.put("device",device);db.insertOrThrow("readings",null,v);MeasurementSpeech.announce(context,m.sys,m.dia,m.pulse);context.sendBroadcast(new Intent(context.getPackageName()+".MEASUREMENT").setPackage(context.getPackageName()));return true;}
public ArrayList<Entry> read(){ArrayList<Entry> entries=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,time,sys,dia,pulse,estimated,status,device FROM readings ORDER BY time DESC",null)){while(c.moveToNext()){Entry e=new Entry();e.id=c.getString(0);e.time=Instant.parse(c.getString(1));e.sys=c.getDouble(2);e.dia=c.getDouble(3);e.pulse=c.isNull(4)?Double.NaN:c.getDouble(4);e.estimated=c.getInt(5)!=0;e.status=c.isNull(6)||!context.getSharedPreferences("bluetooth",0).getBoolean("irregular:"+c.getString(7),false)?null:c.getInt(6);entries.add(e);}}return entries;}
public boolean importPc(String id,Instant t,double sys,double dia,double pulse){if(!License.allowed(context))return false;ContentValues v=new ContentValues();v.put("id",id);v.put("time",t.toString());v.put("sys",sys);v.put("dia",dia);if(Double.isFinite(pulse)&&pulse>0)v.put("pulse",pulse);v.put("estimated",0);v.put("device","pc");return getWritableDatabase().insertWithOnConflict("readings",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1;}
public boolean saveManual(Instant t,double sys,double dia,double pulse){return saveManual(UUID.randomUUID().toString(),t,sys,dia,pulse);} public boolean saveManual(String id,Instant t,double sys,double dia,double pulse){if(!License.allowed(context))return false;
ContentValues v=new ContentValues();v.put("id",id);v.put("time",t.toString());v.put("sys",sys);v.put("dia",dia);if(Double.isFinite(pulse)&&pulse>0)v.put("pulse",pulse);v.put("estimated",0);v.put("device","manual");return getWritableDatabase().insertOrThrow("readings",null,v)!=-1;}
}


